# derive diagonal fill candidates for test
D=set()
for r in range(R):
 for c in range(C):
  if grid[r][c]!=0: continue
  for dr,dc in [(1,1),(1,-1)]:
   rr,cc=r+dr,c+dc
   while 0<=rr<R and 0<=cc<C:
    if grid[rr][cc]==0:
     # all interior 1
     if all(grid[r+k*dr][c+k*dc]==1 for k in range(1,abs(rr-r))):
      D.update((r+k*dr,c+k*dc) for k in range(1,abs(rr-r)))
     break
    rr+=dr; cc+=dc
print(sorted(D),len(D), 'overlap H/V',len(D&fills))

diags=[]
for r in range(R-1):
 for c in range(C-1):
  for dc in [1,-1]:
   rr,cc=r+1,c+dc
   if 0<=cc<C and grid[r][c]==0 and grid[rr][cc]==0:
    bridge1=(r,cc);bridge2=(rr,c)
    diags.append(((r,c),(rr,cc),bridge1 in fills,bridge2 in fills,bridge1,bridge2))
print(diags)
